summary:
bash: cat > /tmp/test_klee.c << 'EOF'
#include <stdio.h>
#include <klee/klee.h>

int main() {
    int x;
    klee_make_symbolic(&x, sizeof(x), "x");
    if (x == 42) {
        printf("x is 42\n");
    } else {
        printf("x is not 42\n");
    }
    return 0;
}
EOF
clang-16 -I/usr/local/include -c -emit-llvm /tmp/test_klee.c -o /tmp/test_klee.bc 2>&1
echo "clang exit=$?"

